/**
 * Application-facing multi-operation transactions.
 *
 * ```ts
 * const result = await db.transaction(async tx => {
 *   tx.collection('users').set('u1', user);
 *   tx.collection('orders').set('o1', order);
 *   tx.collection('audit').set('a1', event);
 * });
 * ```
 *
 * Either every operation commits or none do.
 *
 * The callback **stages** operations; it does not write them. Nothing reaches
 * the authority until the callback returns, at which point the whole
 * transaction is sent as one request and committed as one durable record. That
 * is what makes the guarantee real: there is no window in which some of the
 * operations have been written and others have not.
 *
 * FeltDB does not implement a second transaction mechanism in TypeScript. This
 * builder produces a request for the store's own atomic transaction path, and
 * a runtime that cannot provide that path refuses the transaction rather than
 * silently degrading it into a sequence of independent writes.
 */
/** Thrown when a transaction cannot be committed. Nothing was applied. */
export class AtomicTransactionError extends Error {
    transactionId;
    code;
    status;
    constructor(message, transactionId, code, status, cause) {
        super(message, { cause });
        this.name = 'AtomicTransactionError';
        this.transactionId = transactionId;
        this.code = code;
        this.status = status;
    }
}
/**
 * A transaction was refused because a precondition did not hold.
 *
 * Distinct from every other failure a transaction can have, and carried as a
 * type rather than a message: a conflict means re-read and decide again, while
 * an authentication, network, validation or server error means something else
 * entirely, and a caller must not have to parse prose to tell them apart.
 *
 * A conflict guarantees that **zero** operations committed.
 */
export class ConditionalConflictError extends AtomicTransactionError {
    code = 'PRECONDITION_FAILED';
    failure;
    constructor(message, transactionId, failure) {
        super(message, transactionId);
        this.name = 'ConditionalConflictError';
        this.failure = failure;
    }
}
/**
 * A refusal a conditional write is *allowed* to have, told apart from every
 * other way a commit can fail.
 *
 * The conditional collection helpers report a lost race as a value and raise
 * everything else. That distinction only holds if it is made in one place: a
 * runtime that reports a conflict differently from another would make
 * `putIfAbsent` mean one thing on a file runtime and another against a managed
 * authority, which is the defect these helpers exist to remove.
 *
 * Three shapes reach here, and all three are the same event:
 *
 * - an embedded runtime's `EmbeddedTransactionRejected`, which carries the
 *   code and the structured failure directly;
 * - the direct authority's refused `POST /transactions`, whose body is carried
 *   on the error as `feltdbCode` and `feltdbConflict`;
 * - a managed authority's refused `POST /v1/transactions`, which answers with
 *   HTTP 409 and a `FeltDBServiceError` coded `PRECONDITION_FAILED` or
 *   `CONFLICT`.
 *
 * Anything else -- authentication, schema validation, transport, a 5xx -- is
 * deliberately *not* a conflict. Converting one of those into "someone else
 * won the race" is how a caller silently skips work it was required to do.
 */
export function conditionalRefusal(error) {
    const candidate = error;
    if (!candidate || typeof candidate !== 'object')
        return { conflict: false };
    if (candidate.feltdbCode === 'PRECONDITION_FAILED') {
        return { conflict: true, failure: candidate.feltdbConflict };
    }
    // An authority answers a refused conditional transaction with 409 and a
    // coded body. The status is required as well as the code, so a code that
    // travels on an unrelated failure cannot be read as a lost race -- and a
    // 5xx, a 401 or a transport failure never reaches this branch at all.
    const code = candidate.feltdbCode ?? candidate.code;
    if (candidate.status === 409 && (code === 'PRECONDITION_FAILED' || code === 'CONFLICT')) {
        return { conflict: true, failure: candidate.feltdbConflict };
    }
    return { conflict: false };
}
/**
 * Normalise a precondition to the single wire field.
 *
 * `ifVersion` is the public spelling and `expectedVersion` is the wire's. They
 * are one predicate, so two different values for it is a caller error.
 */
export function normalisePrecondition(condition) {
    const { ifVersion, expectedVersion, ...rest } = condition;
    if (ifVersion !== undefined && expectedVersion !== undefined && ifVersion !== expectedVersion) {
        throw new Error(`precondition on ${condition.collection}:${condition.id} supplies ifVersion `
            + `${ifVersion} and expectedVersion ${expectedVersion}; they are the same predicate`);
    }
    const version = ifVersion ?? expectedVersion;
    return version === undefined ? { ...rest } : { ...rest, expectedVersion: version };
}
function generateTransactionId() {
    const random = Math.random().toString(36).slice(2, 10);
    return `tx_${Date.now().toString(36)}_${random}`;
}
/** Collects operations without performing any I/O. */
export class AtomicTransactionBuilder {
    transactionId;
    staged = [];
    required = [];
    sealed = false;
    constructor(transactionId) {
        this.transactionId = transactionId || generateTransactionId();
    }
    get operations() {
        return this.staged;
    }
    collection(name) {
        if (!name || !name.trim())
            throw new Error('collection name is required');
        const stage = (staged) => {
            // Normalised here so that an `ifVersion` written on an operation cannot
            // be silently ignored — a declared-but-dropped predicate is the defect
            // this whole capability exists to remove.
            const { ifVersion, expectedVersion, ...rest } = staged;
            if (ifVersion !== undefined && expectedVersion !== undefined && ifVersion !== expectedVersion) {
                throw new Error(`${staged.collection}:${staged.id} supplies ifVersion ${ifVersion} and expectedVersion `
                    + `${expectedVersion}; they are the same predicate`);
            }
            const version = ifVersion ?? expectedVersion;
            const operation = version === undefined ? { ...rest } : { ...rest, expectedVersion: version };
            if (this.sealed) {
                throw new Error('this transaction has already been committed; start a new one');
            }
            const duplicate = this.staged.find(existing => existing.collection === operation.collection && existing.id === operation.id);
            if (duplicate) {
                // Two writes to one record inside one transaction would make the
                // outcome depend on staging order rather than on the transaction.
                throw new Error(`transaction already stages ${operation.collection}:${operation.id}; `
                    + 'a transaction may write each record at most once');
            }
            this.staged.push(operation);
        };
        const surface = {
            set: (id, value, options) => {
                stage({
                    collection: name,
                    id: String(id),
                    value: value,
                    requireAbsent: options?.requireAbsent,
                    ifVersion: options?.ifVersion,
                    expectedVersion: options?.expectedVersion,
                    expectedEpoch: options?.expectedEpoch,
                    expectedLeaseId: options?.expectedLeaseId,
                });
                return surface;
            },
            insert: (value, id, options) => surface.set(id, value, options),
            delete: (id, options) => {
                stage({
                    collection: name,
                    id: String(id),
                    requireAbsent: options?.requireAbsent,
                    ifVersion: options?.ifVersion,
                    expectedVersion: options?.expectedVersion,
                    expectedEpoch: options?.expectedEpoch,
                    expectedLeaseId: options?.expectedLeaseId,
                });
                return surface;
            },
        };
        return surface;
    }
    get preconditions() {
        return this.required;
    }
    require(condition) {
        if (this.sealed) {
            throw new Error('this transaction has already been committed; start a new one');
        }
        if (!condition.collection?.trim() || !String(condition.id ?? '').trim()) {
            throw new Error('a precondition requires a collection and an id');
        }
        const normalised = normalisePrecondition(condition);
        const constrains = normalised.requireAbsent === true
            || normalised.expectedVersion !== undefined
            || normalised.expectedEpoch !== undefined
            || normalised.expectedLeaseId !== undefined;
        if (!constrains) {
            // Refused rather than ignored: a precondition that constrains nothing
            // reads as protection and provides none.
            throw new Error(`precondition on ${condition.collection}:${condition.id} constrains nothing`);
        }
        this.required.push({ ...normalised, id: String(condition.id) });
        return this;
    }
    /** Freeze the builder and produce the request to send. */
    seal() {
        this.sealed = true;
        return {
            transactionId: this.transactionId,
            operations: [...this.staged],
            preconditions: [...this.required],
        };
    }
}
